cases.setup:
printf '# tool\n\nA tiny demo tool.\n' > README.md
cat > tool.sh <<'EOF'
#!/bin/sh
[ "$1" = "--count" ] || { echo 'usage: tool.sh --count N' >&2; exit 2; }
i=0; while [ $i -lt "$2" ]; do echo line; i=$((i+1)); done
EOF

cat > a.sh <<'EOF'
#!/bin/sh
log() { echo "[$1] $2"; }
log a start
EOF
cat > b.sh <<'EOF'
#!/bin/sh
log() { echo "[$1] $2"; }
log b start
EOF

cases.solution:
cat > readfile.sh <<'EOF'
#!/bin/sh
case "$1" in
  /*|*..*) echo 'invalid path' >&2; exit 2;;
esac
cat "data/$1"
EOF
